  /**
   * The parts of a building BQ around the lines: title, place, sections, contingency, notes and drawings. Checked and
   * trimmed here; nothing is kept for a part that was not sent.
   */
  private amBqDocument(input: {
    title?: unknown;
    location?: unknown;
    sections?: unknown;
    contingencyPct?: unknown;
    notes?: unknown;
    drawings?: unknown;
  }): Pick<AmBq, 'title' | 'location' | 'sections' | 'contingencyPct' | 'notes' | 'drawings'> {
    const out: Pick<AmBq, 'title' | 'location' | 'sections' | 'contingencyPct' | 'notes' | 'drawings'> = {};
    const title = String(input.title ?? '').trim().slice(0, 200);
    if (title) out.title = title;
    const location = String(input.location ?? '').trim().slice(0, 200);
    if (location) out.location = location;
    if (input.sections != null) {
      if (!Array.isArray(input.sections) || input.sections.length > 26) throw new BadRequest('A BQ has at most 26 sections.');
      const seen = new Set<string>();
      out.sections = input.sections.map((x: { code?: unknown; title?: unknown }, i) => {
        const code = String(x?.code ?? '').trim().toUpperCase();
        const t = String(x?.title ?? '').trim().slice(0, 120);
        if (!/^[A-Z]{1,2}$/.test(code) || seen.has(code)) throw new BadRequest(`Section ${i + 1}: give a letter that is not used twice.`);
        if (!t) throw new BadRequest(`Section ${code}: give its title.`);
        seen.add(code);
        return { code, title: t };
      });
      if (!out.sections.length) delete out.sections;
    }
    if (input.contingencyPct != null && input.contingencyPct !== '') {
      const pct = Math.round(Number(input.contingencyPct) * 100) / 100;
      if (!(pct >= 0 && pct <= 20)) throw new BadRequest('The contingency must be 0% to 20%.');
      out.contingencyPct = pct;
    }
    if (input.notes != null) {
      if (!Array.isArray(input.notes) || input.notes.length > 40) throw new BadRequest('A BQ has at most 40 notes.');
      const notes = input.notes.map((n) => String(n ?? '').trim().slice(0, 400)).filter(Boolean);
      if (notes.length) out.notes = notes;
    }
    if (input.drawings != null) {
      if (!Array.isArray(input.drawings) || input.drawings.length > 30) throw new BadRequest('A BQ lists at most 30 drawings.');
      const drawings = input.drawings
        .map((d: { ref?: unknown; title?: unknown }) => ({ ref: String(d?.ref ?? '').trim().slice(0, 20), title: String(d?.title ?? '').trim().slice(0, 160) }))
        .filter((d) => d.ref || d.title);
      if (drawings.some((d) => !d.ref || !d.title)) throw new BadRequest('Each drawing needs its number and its title.');
      if (drawings.length) out.drawings = drawings;
    }
    return out;
  }

