/** Most firearms out at the same moment in a window, from issue and return times. */
function peakOut(movements: ArmsMovement[], fromMs: number, toMsEnd: number): number {
  const ev: [number, number][] = [];
  for (const m of movements) {
    const a = Math.max(toMs(m.issuedAt), fromMs);
    const b = Math.min(m.returnedAt ? toMs(m.returnedAt) : toMsEnd, toMsEnd);
    if (a < b) ev.push([a, 1], [b, -1]);
  }
  ev.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
  let n = 0;
  let peak = 0;
  for (const [, d] of ev) peak = Math.max(peak, (n += d));
  return peak;
}

/** Home items for open attendance alerts, repeated to the PIC until someone acts (Shahirah, 25 Oct 2026). */
function attendanceHomeItems(issues: AttendanceIssueView[], companyId: Id): HomeItem[] {
  return issues
    .filter((i) => i.repeating)
    .map((i) => ({
      tone: i.issue === 'NO_SHOW' || i.issue === 'POST_EMPTY' || i.issue === 'FACE_NOT_MATCHED' ? ('crit' as const) : ('warn' as const),
      tag: `Alert ×${i.alertsSent}`,
      title: `${ATTENDANCE_ISSUE_LABEL[i.issue]}: ${i.personName ?? i.postName}`,
      detail: `${i.siteName} · ${i.postName || 'not rostered'} · from ${i.raisedAt.slice(11, 16)} · repeats every ${RULES.attendanceAlertRepeat.value} min until acted on`,
      go: { view: 'attendance' as const, companyId },
    }));
}

