/** The seats a day needs under the settings: each shift window times the posts. */
export function cmsSeats(set: CmsSettings, date: IsoDate): CmsShift[] {
  const hours = set.shiftPattern === '2x12' ? 12 : 8;
  const count = 24 / hours;
  const seats: CmsShift[] = [];
  const first = toMs(myt(date, set.firstShiftStart));
  for (let i = 0; i < count; i++) {
    const startMs = first + i * hours * 3_600_000;
    const start = fromMs(startMs);
    const end = fromMs(startMs + hours * 3_600_000);
    const hhmm = start.slice(11, 16).replace(':', '');
    const add = (post: CmsPost, n: number) => {
      for (let k = 1; k <= n; k++)
        seats.push({
          id: `cms-${date}-${hhmm}-${hours}h-${post === 'HEAD_CONTROL' ? 'hc' : 'mo'}-${k}`,
          date,
          start,
          end,
          post,
          seat: k,
          staffName: null,
          clockIn: null,
          handoverAt: null,
          handoverNote: null,
        });
    };
    add('HEAD_CONTROL', set.headControlPerShift);
    add('MONITOR_OFFICER', set.monitorOfficersPerShift);
  }
  return seats;
}

function cmsOrder(a: CmsShift, b: CmsShift): number {
  return a.start.localeCompare(b.start) || a.post.localeCompare(b.post) || a.seat - b.seat;
}

export function cmsShiftState(s: CmsShift, nowMs: number, graceMin: number): 'uncovered' | 'done' | 'later' | 'on_duty' | 'no_show' | 'awaiting' {
  if (!s.staffName) return 'uncovered';
  if (toMs(s.end) <= nowMs) return 'done';
  if (toMs(s.start) > nowMs) return 'later';
  if (s.clockIn) return 'on_duty';
  return nowMs - toMs(s.start) > graceMin * 60_000 ? 'no_show' : 'awaiting';
}

function isArmsOnly(user: User): boolean {
  return user.role === 'pwvsb_officer' && user.department === 'arms_control';
}

const CLAIM_VEHICLES: ClaimVehicle[] = ['CAR', 'MOTORCYCLE', 'COMPANY_CAR'];

const SEVERITY_ORDER: Record<Severity, number> = { P1: 0, P2: 1, P3: 2, P4: 3 };

function caseOrder(a: CaseView, b: CaseView): number {
  const done = (c: CaseView) => (c.status === 'resolved' || c.status === 'closed' ? 1 : 0);
  return done(a) - done(b) || SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity] || b.openedAt.localeCompare(a.openedAt);
}

/**
 * Whose records a PWVSB department works with (Fauzan, 26 Oct 2026): FWM only foreign workers, central HR only local
 * workers and staff. Group leadership and company staff are not narrowed here.
 */
function inLine(user: User, person: Pick<Person, 'nationality'>): boolean {
  if (user.role !== 'pwvsb_officer' || isGroupLeader(user)) return true;
  if (user.department === 'fwm') return person.nationality !== 'MY';
  if (user.department === 'hr') return person.nationality === 'MY';
  return true;
}

const JA_SEVERITY: Severity[] = ['P1', 'P2', 'P3', 'P4'];
const JA_PAPERS: JaPaper[] = ['PLKS', 'PASSPORT', 'FOMEMA', 'FWIG', 'SPIKPA', 'KDN_LETTER'];
const JA_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Check one JA record's fields and keep only what Prima uses. */
function jaBody(dataset: JaDataset, it: Record<string, unknown>): JaPayroll | JaWorker | JaIncident | JaPaySummary {
  const text = (v: unknown, name: string, max = 500) => {
    if (typeof v !== 'string' || !v.trim() || v.length > max) throw new BadRequest(`${name} is missing or too long.`);
    return v.trim();
  };
  const opt = (v: unknown, max = 200) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
  const money = (v: unknown, name: string) => {
    if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) throw new BadRequest(`${name} must be an amount in RM.`);
    return Math.round(v * 100) / 100;
  };
  const date = (v: unknown, name: string) => {
    if (v == null) return null;
    if (typeof v !== 'string' || !JA_DATE.test(v)) throw new BadRequest(`${name} must be a date like 2026-10-26.`);
    return v;
  };
  const time = (v: unknown, name: string) => {
    if (typeof v !== 'string' || Number.isNaN(Date.parse(v))) throw new BadRequest(`${name} must be a date and time.`);
    return fromMs(Date.parse(v));
  };
  if (dataset === 'payroll') {
    const period = text(it.period, 'period', 7);
    if (!/^\d{4}-\d{2}$/.test(period)) throw new BadRequest('period must be a month like 2026-10.');
    const status = it.status;
    if (status !== 'draft' && status !== 'approved' && status !== 'paid') throw new BadRequest('status must be draft, approved or paid.');
    const headcount = it.headcount;
    if (typeof headcount !== 'number' || !Number.isInteger(headcount) || headcount < 0) throw new BadRequest('headcount must be a whole number.');
    return {
      period,
      headcount,
      gross: money(it.gross, 'gross'),
      net: money(it.net, 'net'),
      employerEpf: money(it.employerEpf, 'employerEpf'),
      employerSocso: money(it.employerSocso, 'employerSocso'),
      employerEis: money(it.employerEis, 'employerEis'),
      ...(it.employeeSocso == null ? {} : { employeeSocso: money(it.employeeSocso, 'employeeSocso') }),
      ...(it.employeeLindung == null ? {} : { employeeLindung: money(it.employeeLindung, 'employeeLindung') }),
      ...(it.employeeEis == null ? {} : { employeeEis: money(it.employeeEis, 'employeeEis') }),
      pcb: money(it.pcb, 'pcb'),
      status,
      approvedBy: opt(it.approvedBy),
      approvedAt: it.approvedAt == null ? null : time(it.approvedAt, 'approvedAt'),
      paidOn: date(it.paidOn, 'paidOn'),
    };
  }
  if (dataset === 'paySummary') {
    const period = text(it.period, 'period', 7);
    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(period)) throw new BadRequest('period must be a month like 2026-10.');
    const otHours = it.otHours;
    if (typeof otHours !== 'number' || !Number.isFinite(otHours) || otHours < 0 || otHours > 400) throw new BadRequest('otHours must be a number of hours.');
    if (it.deductions != null && !Array.isArray(it.deductions)) throw new BadRequest('deductions must be a list.');
    const deductions = ((it.deductions as unknown[] | undefined) ?? []).slice(0, 30).map((x) => {
      const d = (x ?? {}) as Record<string, unknown>;
      return { kind: text(d.kind, 'deduction kind', 60), amount: money(d.amount, 'deduction amount') };
    });
    return {
      staffNo: text(it.staffNo, 'staffNo', 40),
      period,
      basic: money(it.basic, 'basic'),
      otHours: Math.round(otHours * 100) / 100,
      otPay: money(it.otPay, 'otPay'),
      allowances: it.allowances == null ? 0 : money(it.allowances, 'allowances'),
      deductions,
      gross: money(it.gross, 'gross'),
      net: money(it.net, 'net'),
      paidOn: date(it.paidOn, 'paidOn'),
    };
  }
  if (dataset === 'worker') {
    const statuses: JaWorker['status'][] = ['active', 'home_leave', 'exit_pending', 'exited', 'absconded', 'other'];
    const status = statuses.includes(it.status as JaWorker['status']) ? (it.status as JaWorker['status']) : 'other';
    if (!Array.isArray(it.papers)) throw new BadRequest('papers must be a list.');
    const papers = it.papers.slice(0, 20).map((x) => {
      const p = (x ?? {}) as Record<string, unknown>;
      if (!JA_PAPERS.includes(p.paper as JaPaper)) throw new BadRequest(`Unknown paper ${String(p.paper)}.`);
      return { paper: p.paper as JaPaper, expiresOn: date(p.expiresOn, 'expiresOn'), renewalSubmittedOn: date(p.renewalSubmittedOn, 'renewalSubmittedOn') };
    });
    return {
      staffNo: text(it.staffNo, 'staffNo', 40),
      name: text(it.name, 'name', 200),
      nationality: text(it.nationality, 'nationality', 60),
      status,
      serviceYear: typeof it.serviceYear === 'number' ? it.serviceYear : null,
      siteCode: opt(it.siteCode, 40),
      hostel: opt(it.hostel, 120),
      papers,
    };
  }
  const severity = it.severity as Severity;
  if (!JA_SEVERITY.includes(severity)) throw new BadRequest('severity must be P1 to P4.');
  if (it.status !== 'open' && it.status !== 'closed') throw new BadRequest('status must be open or closed.');
  return {
    occurredAt: time(it.occurredAt, 'occurredAt'),
    siteCode: opt(it.siteCode, 40),
    category: text(it.category, 'category', 80),
    severity,
    status: it.status,
    summary: text(it.summary, 'summary', 2000),
    reportedBy: opt(it.reportedBy),
    closedAt: it.closedAt == null ? null : time(it.closedAt, 'closedAt'),
  };
}

/** Mask an IC or passport for the person record: the last four characters only. */
export function maskIdNumber(full: string): string {
  const t = full.replace(/\s/g, '');
  return t.length <= 4 ? '****' : `${'*'.repeat(Math.min(8, t.length - 4))}${t.slice(-4)}`;
}

/** Read one guard from JA (slice 3G). Full numbers come back apart so they are never kept on the JA record. */
export function jaGuardParse(it: Record<string, unknown>): { guard: JaGuard; idFull: string | null; accountFull: string | null } {
  const text = (v: unknown, name: string, max = 200) => {
    if (typeof v !== 'string' || !v.trim() || v.length > max) throw new BadRequest(`${name} is missing or too long.`);
    return v.trim();
  };
  const opt = (v: unknown, max = 120) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
  const date = (v: unknown, name: string, required = false) => {
    if (v == null && !required) return null;
    if (typeof v !== 'string' || !JA_DATE.test(v)) throw new BadRequest(`${name} must be a date like 2026-10-26.`);
    return v;
  };
  const roles: JaGuard['role'][] = ['guard', 'supervisor', 'patrol_officer'];
  if (!roles.includes(it.role as JaGuard['role'])) throw new BadRequest('role must be guard, supervisor or patrol_officer.');
  const statuses: JaGuard['status'][] = ['active', 'suspended', 'left'];
  if (!statuses.includes(it.status as JaGuard['status'])) throw new BadRequest('status must be active, suspended or left.');
  const idFull = opt(it.idFull, 30);
  if (idFull && !/^[A-Za-z0-9-]{6,30}$/.test(idFull)) throw new BadRequest('idFull must be an IC or passport number.');
  const accountFull = opt(it.accountFull, 30);
  if (accountFull && !/^[0-9-]{6,30}$/.test(accountFull)) throw new BadRequest('accountFull must be digits.');
  if (it.basicPay != null && (typeof it.basicPay !== 'number' || !Number.isFinite(it.basicPay) || it.basicPay < 0)) throw new BadRequest('basicPay must be an amount in RM.');
  const paper = (v: unknown, name: string, withExpiry: boolean) => {
    if (v == null) return null;
    const o = v as Record<string, unknown>;
    const number = text(o.number ?? o.certificateNo, `${name} number`, 60);
    const on = date(o.issuedOn ?? o.doneOn, `${name} date`, true)!;
    if (!withExpiry) return { certificateNo: number, doneOn: on };
    return { number, issuedOn: on, expiresOn: date(o.expiresOn, `${name} expiry`, true)! };
  };
  const guard: JaGuard = {
    staffNo: text(it.staffNo, 'staffNo', 40),
    name: text(it.name, 'name'),
    nationality: text(it.nationality, 'nationality', 60),
    role: it.role as JaGuard['role'],
    status: it.status as JaGuard['status'],
    dob: date(it.dob, 'dob', true)!,
    hiredOn: date(it.hiredOn, 'hiredOn', true)!,
    state: opt(it.state, 60),
    siteCode: opt(it.siteCode, 40),
    phone: opt(it.phone, 30),
    idMasked: idFull ? maskIdNumber(idFull) : (opt(it.idMasked, 30) ?? '****'),
    basicPay: typeof it.basicPay === 'number' ? Math.round(it.basicPay * 100) / 100 : null,
    bankName: opt(it.bankName, 60),
    accountMasked: accountFull ? maskIdNumber(accountFull) : opt(it.accountMasked, 30),
    epfNo: opt(it.epfNo, 30),
    socsoNo: opt(it.socsoNo, 30),
    kdnCard: paper(it.kdnCard, 'kdnCard', true) as JaGuard['kdnCard'],
    vettingSubmittedOn: date(it.vettingSubmittedOn, 'vettingSubmittedOn'),
    vettingRef: opt(it.vettingRef, 60),
    csg: paper(it.csg, 'csg', false) as JaGuard['csg'],
    tng: paper(it.tng, 'tng', false) as JaGuard['tng'],
  };
  // When a guard left (group employment history, Fauzan 4 Nov 2026): optional, only with status left.
  const leftOn = date(it.leftOn, 'leftOn');
  const hows = ['resigned', 'terminated', 'contract_end', 'retired'] as const;
  if (it.leftHow != null && !hows.includes(it.leftHow as never)) throw new BadRequest('leftHow must be resigned, terminated, contract_end or retired.');
  if ((leftOn || it.leftHow != null) && guard.status !== 'left') throw new BadRequest('leftOn and leftHow are sent only with status left.');
  if (leftOn && leftOn < guard.hiredOn) throw new BadRequest('leftOn comes after hiredOn.');
  if (!!leftOn !== (it.leftHow != null)) throw new BadRequest('Send leftOn and leftHow together, or neither.');
  if (leftOn) guard.leftOn = leftOn;
  if (it.leftHow != null) guard.leftHow = it.leftHow as (typeof hows)[number];
  return { guard, idFull, accountFull };
}

export function jaOwns(area: JaArea): boolean {
  return RULES.jaGroupApp.value.owns.includes(area);
}

/** Agenda lines, without numbering or bullets the organiser typed. */
export function agendaItems(agenda: string): string[] {
  return (agenda ?? '')
    .split(/\r?\n/)
    .map((x) => x.replace(/^\s*(?:\d+[.)]|[-*•])\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 40);
}

/** The pre-briefing checklist for a kind of meeting (rule MTG-PREP). */
export function defaultMeetingPrep(kind: Meeting['kind']): NonNullable<Meeting['prep']> {
  const r = RULES.meetingPrep.value;
  return [...r.common, ...(r.byKind[kind] ?? [])].map((label) => ({ label, done: false, by: null, at: null }));
}

/** Old and new value of every field changed on a record form, for the audit log (Fauzan, 27 Oct 2026). */
export function recordChanges(spec: (typeof RECORD_KINDS)[RecordKind], before: RecordValues, after: RecordValues): string {
  const show = (v: unknown) => (v === null || v === undefined || v === '' ? 'empty' : v === true ? 'yes' : v === false ? 'no' : String(v));
  return spec.fields
    .filter((f) => f.key in after && show(before[f.key]) !== show(after[f.key]))
    .map((f) => {
      const val = (x: unknown) => (f.restricted && show(x) !== 'empty' ? `****${String(x).slice(-4)}` : show(x));
      return `${f.label}: ${val(before[f.key])} → ${val(after[f.key])}`;
    })
    .join('; ');
}

/** A firearm as every screen but the Arms Control form sees it: the full serial number left out. */
function withoutSerial(f: Firearm): Firearm {
  const { serial: _serial, ...rest } = f;
  return rest;
}

/**
 * When an unpaid unit's status was last updated and when the next update is due (rule AM-WATCH, every 10 days until
 * paid). A follow-up (other than a letter still waiting for approval) or a payment counts as an update. The clock starts
 * on the 1st of the oldest unpaid month. Null when nothing is unpaid.
 */
function rentUpdate(t: AmTenancy | null, today: IsoDate, everyDays: number) {
  if (!t) return null;
  const unpaid = t.invoices.filter((i) => i.paid < i.amount && i.period <= today.slice(0, 7));
  if (!unpaid.length) return null;
  const since = `${unpaid.map((i) => i.period).sort()[0]}-01`;
  const marks = [
    t.lastContactOn,
    ...(t.followUps ?? []).filter((f) => (f.action !== 'LETTER' && f.action !== 'NOTICE') || f.approval?.approve).map((f) => f.on),
    ...(t.payments ?? []).filter((p) => !p.reversed).map((p) => p.on),
  ].filter((d): d is IsoDate => !!d && d >= since);
  const last = marks.sort().at(-1) ?? null;
  const nextOn = addDays(last ?? since, everyDays);
  return { lastOn: last, nextOn, due: nextOn <= today, daysLate: Math.max(0, daysBetween(nextOn, today)) };
}

function pickKeys(r: Record<string, unknown>, keys: string[]): RecordValues {
  const out: RecordValues = {};
  for (const k of keys) {
    const v = r[k];
    out[k] = v === undefined ? null : (v as RecordValues[string]);
  }
  return out;
}

async function closeAccessInStore(tx: Store, userId: Id, from: IsoDate, closed: NonNullable<User['accessClosed']>): Promise<number> {
  await tx.update('users', userId, { accessClosedFrom: from, accessClosed: closed });
  const lastDay = addDays(from, -1);
  let n = 0;
  for (const g of await tx.list('grants', { userId }))
    if (g.validTo > lastDay) {
      await tx.update('grants', g.id, { validTo: lastDay < g.validFrom ? g.validFrom : lastDay });
      n += 1;
    }
  return n;
}

/**
 * Website, social media and email help requests (opened from Websites, sourceRef `web:`) are confirmed by the IT
 * Manager, or by the IT Lead when the IT Manager fixed it; never by the person who fixed it (Fauzan, 1 Nov 2026, Q7).
 */
export function webTicketConfirmer(
  t: Pick<ItTicket, 'status' | 'resolvedById' | 'assignedToId' | 'sourceRef' | 'confirmedAt'>,
  user: Pick<User, 'id' | 'department' | 'itRole'>,
  resolverItRole: string | null | undefined,
): boolean {
  if (!t.sourceRef?.startsWith('web:') || t.status !== 'resolved' || t.confirmedAt) return false;
  if (user.department !== 'it' || itMayHaveFixed(t, user)) return false;
  return resolverItRole === 'manager' ? user.itRole === 'lead' : user.itRole === 'manager';
}

/**
 * A refusal that keeps what was already saved in the same request (review finding, 1 Nov 2026): a lapsed approval is
 * returned to the preparer and logged even when the release or return that found it is refused. The API commits the
 * transaction before answering 400; anything else that throws rolls back as usual.
 */
export class RefusedAfterSave extends BadRequest {
  constructor(message: string) {
    super(message);
    this.name = 'RefusedAfterSave';
  }
}
/** Memo read reminder: a memo not opened this many days after publishing comes back on the reader's home (5F). */
const MEMO_REMIND_DAYS = 3;

/**
 * Arms trading is switched off. Thrown without writing anything, because the caller's transaction rolls back on a throw;
 * the caller writes the refusal with logTradeRefusal in a transaction of its own.
 */
export class TradingOff extends BadRequest {
  constructor(public readonly what: string, public readonly companyId: string | null) {
    super('Arms trading is switched off until the CEO starts it.');
    this.name = 'TradingOff';
  }
}

/**
 * CMS coverage and response KPIs over the last 24 hours (masterplan §195): time to acknowledge against the CMS setting,
 * alarms still waiting past it, false-alarm rate, and how many linked site systems are online, offline or unknown.
 * Unknown is never counted as online. Read-only figures for the CMS board; the target is the existing CMS setting.
 */
export function cmsResponseKpis(companies: Company[], alarmsAll: SiteAlarm[], systems: SiteSystem[], sitesAll: Site[], targetSec: number, nowMs: number, contracts: Contract[] = []) {
  const from = nowMs - 24 * 3_600_000;
  const pick = (list: number[], p: number) => {
    if (!list.length) return null;
    const sorted = [...list].sort((x, y) => x - y);
    return sorted[Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1))];
  };
  const figures = (list: SiteAlarm[]) => {
    const ack = list.filter((a) => a.ackAt).map((a) => Math.max(0, Math.floor((toMs(a.ackAt!) - toMs(a.at)) / 1000)));
    const closed = list.filter((a) => a.status === 'closed');
    const falseN = closed.filter((a) => a.verdict === 'false').length;
    return {
      alarms: list.length,
      fromCmsApp: list.filter((a) => a.cmsEventId).length,
      acknowledged: ack.length,
      ackMedianSec: pick(ack, 50),
      ackP90Sec: pick(ack, 90),
      ackOverTarget: ack.filter((x) => x > targetSec).length,
      waitingOverTarget: list.filter((a) => a.status === 'new' && (nowMs - toMs(a.at)) / 1000 > targetSec).length,
      closed: closed.length,
      falseAlarms: falseN,
      falseRatePct: closed.length ? Math.round((falseN / closed.length) * 1000) / 10 : null,
    };
  };
  const coverage = (sys: SiteSystem[], sites: Site[]) => {
    const linked = sys.filter((x) => x.linked);
    const unknown = linked.filter((x) => x.status === 'unknown').length;
    const linkedSites = new Set(linked.map((x) => x.siteId));
    return {
      linkedSystems: linked.length,
      online: linked.filter((x) => x.status === 'online').length,
      offline: linked.filter((x) => x.status === 'offline' || x.status === 'not_recording').length,
      unknown,
      unknownPct: linked.length ? Math.round((unknown / linked.length) * 1000) / 10 : null,
      sitesNotLinked: sites.filter((x) => !linkedSites.has(x.id)).length,
    };
  };
  const recent = alarmsAll.filter((a) => toMs(a.at) >= from && toMs(a.at) <= nowMs);
  // Coverage in contracted minutes: each site's signed CMS monitoring hours in the period, less the minutes every linked
  // system was reported down; minutes CMS cannot speak for are unknown, never covered. Not proof of recording integrity.
  const live = contracts.filter((c) => c.cmsService && c.state !== 'terminated');
  const cov = live.flatMap((c) =>
    c.cmsService!.sites.map((x) => ({
      contractId: c.id,
      ref: c.ref,
      companyId: c.companyId,
      siteName: sitesAll.find((s) => s.id === x.siteId)?.name ?? x.siteId,
      window: `${x.from}-${x.to}`,
      ...contractedCoverage(x.siteId, x, systems, from, nowMs),
    })),
  );
  const sum = (list: typeof cov) => {
    const t = list.reduce((a, r) => ({ c: a.c + r.contractedMin, r: a.r + r.reachableMin, d: a.d + r.downMin, u: a.u + r.unknownMin }), { c: 0, r: 0, d: 0, u: 0 });
    const known = t.c - t.u;
    return { contractedMin: t.c, reachableMin: t.r, downMin: t.d, unknownMin: t.u, reachablePct: known > 0 ? Math.round((t.r / t.c) * 1000) / 10 : null };
  };
  return {
    from: fromMs(from),
    targetSec,
    contracted: { ...sum(cov), sites: cov, contractsWithoutScope: contracts.filter((c) => !c.cmsService && (c.state === 'active' || c.state === 'mobilising' || c.state === 'ready')).length },
    all: figures(recent),
    coverage: coverage(systems, sitesAll),
    byCompany: companies
      .filter((c) => sitesAll.some((x) => x.companyId === c.id))
      .map((c) => ({
        companyId: c.id,
        companyName: c.name,
        ...figures(recent.filter((a) => a.companyId === c.id)),
        coverage: coverage(
          systems.filter((x) => x.companyId === c.id),
          sitesAll.filter((x) => x.companyId === c.id),
        ),
      })),
  };
}

/** Whether the JA Group app is the system of record for an area (rule SYS-JA-OWNS); Prima's own version is then switched off. */
/**
 * The state a site is in: its branch's state, or the site's own state where no branch is set up. A clean-slate database
 * has no branches and no screen creates them, so without this OMs and Regional OMs would cover no sites (go-live
 * readiness, 2 Nov 2026).
 */
export function siteStateOf(site: Pick<Site, 'branchId' | 'state'>, branchState: Map<Id, string>): string {
  return (site.branchId ? branchState.get(site.branchId) : undefined) ?? site.state ?? '';
}

export { onOpsSide } from './ops-access';
/** Decode strict base64 to bytes in Node and the browser alike; null when it is not clean base64. */
function decodeBase64(b64: string): Uint8Array | null {
  if (b64.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(b64)) return null;
  try {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  } catch {
    return null;
  }
}

/** SHA-256 of an evidence file's decoded bytes (not of its data-URL text, which carries a changeable type label). */
export function actEvidenceHash(dataUrl: string): string | null {
  const m = /^data:[^;,]+;base64,(.*)$/.exec(dataUrl);
  const bytes = m ? decodeBase64(m[1]) : null;
  return bytes ? toHex(sha256Bytes(bytes)) : null;
}
/** An ACT refusal with a plain reason; still an AccessDenied (HTTP 403), without the company-grant wording. */
class ActDenied extends AccessDenied {
  constructor(reason: string) {
    super('view', '');
    this.message = reason;
  }
}

function worstTone(findings: OfficeFinding[]): OfficeTone {
  if (findings.some((f) => f.tone === 'crit')) return 'crit';
  if (findings.some((f) => f.tone === 'warn')) return 'warn';
  if (findings.some((f) => f.tone === 'neutral')) return 'neutral';
  return 'ok';
}

/**
 * Who works the police help board: the company manager and admin executives ask; Arms Control assigns and records;
 * CMS and leaders who see arms detail only monitor (Fauzan, 3 Nov 2026: Arms Control coordinates, company authorises).
 */
function policeHelpRole(user: User): 'asker' | 'arms' | 'monitor' | null {
  if (user.role === 'company_manager' || user.role === 'admin_exec') return 'asker';
  if (isArmsOnly(user)) return 'arms';
  if (isGroupRole(user) && seesArmsDetail(user)) return 'monitor';
  return null;
}

/** Time slip settlements in progress per store, so they run one at a time in this process. */
const settleQueue = new WeakMap<Store, Promise<unknown>>();

/** Offboarding in a store with no database function (the browser test version and tests): the same two writes. */
/** The browser test version's history lookup; PostgreSQL runs prima.group_history_lookup instead. */
async function groupHistoryLookupInStore(store: Store, idKey: string, withNotes: boolean, population: 'all' | 'local' | 'foreign'): Promise<GroupHistoryLookupRow> {
  const links = await store.list('personLinks', { idKey });
  const gids = [...new Set(links.map((l) => l.groupPersonId))];
  const groups = (await Promise.all(gids.map((g) => store.get('groupPeople', g)))).filter(
    (g): g is GroupPerson => !!g && !g.mergedInto && (population === 'all' || (population === 'foreign') === g.foreign),
  );
  const companies = await store.list('companies', {});
  const companyNames: Record<Id, string> = {};
  for (const c of companies) companyNames[c.id] = c.name;
  const notes = withNotes ? (await Promise.all(groups.map((g) => store.get('groupPersonNotes', g.id)))).flatMap((n) => n?.rehire ?? []) : null;
  return { groups, companyNames, rehireNotes: notes };
}

/** The browser test version's mark by lookup; PostgreSQL runs prima.history_set_mark instead. */
async function historySetMarkInStore(tx: Store, idKey: string, mark: NonNullable<GroupPerson['rehire']>, entry: GroupPersonNotes['rehire'][number], actorPersonId: Id | null): Promise<Id[]> {
  const links = await tx.list('personLinks', { idKey });
  const gids = [...new Set(links.map((l) => l.groupPersonId))];
  // Any record of the same person, including ones linked by hand under another number.
  const all = (await Promise.all(gids.map((g) => tx.list('personLinks', { groupPersonId: g })))).flat();
  if (actorPersonId && all.some((l) => l.personId === actorPersonId)) throw new BadRequest('Someone else decides about your own history.');
  const out: Id[] = [];
  for (const gid of gids) {
    const g = await tx.get('groupPeople', gid);
    if (!g || g.mergedInto) continue;
    const notes = await tx.get('groupPersonNotes', gid);
    if (notes) await tx.update('groupPersonNotes', gid, { rehire: [...notes.rehire, entry] });
    else await tx.insert('groupPersonNotes', { id: gid, foreign: g.foreign, rehire: [entry], oldRecords: [] });
    await tx.update('groupPeople', gid, { rehire: mark, updatedAt: mark.setAt });
    out.push(gid);
  }
  return out;
}

/** Trimmed text within a length, refusing anything that looks like a login secret (CMS readiness keeps no secrets). */
function cleanText(v: unknown, label: string, max: number): string {
  if (v === undefined || v === null) return '';
  if (typeof v !== 'string') throw new BadRequest(`${label} must be text.`);
  const t = v.trim();
  if (t.length > max) throw new BadRequest(`${label} is too long (${max} characters at most).`);
  if (looksLikeSecret(t)) throw new BadRequest(`${label} looks like a password or code. Record only who holds the login, never the login itself.`);
  return t;
}

// ---------- FWM board in both Prima and the JA Group app (Fauzan, 5 Nov 2026) ----------

/** One foreign-worker paper as the board shows it: Prima's date, the JA app's date, the ladder and acknowledgements. */
function fwPaperView(a: {
  paper: FwPaper;
  credential: Credential | null;
  renewals: FwRenewal[];
  ja: JaRecord | null;
  jaStale: boolean;
  level: FwLevel | null;
  today: IsoDate;
}) {
  const c = a.credential;
  const jaPaper = a.ja?.worker?.papers.find((x) => JA_TO_FW_PAPER[x.paper] === a.paper) ?? null;
  const ja = a.ja?.worker
    ? { recordId: a.ja.id, expiresOn: jaPaper?.expiresOn ?? null, renewalSubmittedOn: jaPaper?.renewalSubmittedOn ?? null, stale: a.jaStale, updatedAt: a.ja.sourceUpdatedAt }
    : null;
  const primaExpiresOn = c?.expiresOn ?? null;
  const datesDiffer = !!(primaExpiresOn && ja?.expiresOn && primaExpiresOn !== ja.expiresOn);
  // When the two apps differ, count to the earlier date until FWM settles it: never later than either says.
  const counted = primaExpiresOn && ja?.expiresOn ? (ja.expiresOn < primaExpiresOn ? ja.expiresOn : primaExpiresOn) : (primaExpiresOn ?? ja?.expiresOn ?? null);
  const countedFrom: 'prima' | 'ja' | null = !counted ? null : counted === primaExpiresOn ? 'prima' : 'ja';
  const source: 'prima' | 'ja' | 'sample' | null = c ? (c.source ?? 'sample') : null;
  const base = {
    paper: a.paper,
    label: FW_PAPER_LABEL[a.paper],
    credentialId: c?.id ?? null,
    // Passport numbers never leave as more than their last 4 characters, even on older or sample rows.
    number: c ? (a.paper === 'PASSPORT' ? fwPaperNumber('PASSPORT', c.number) || null : c.number) : null,
    issuedOn: c?.issuedOn ?? null,
    primaExpiresOn,
    source,
    ja,
    datesDiffer,
    countedFrom,
  };
  if (!counted) {
    return { ...base, expiresOn: null, deadline: null, daysLeft: null, stage: null, renewal: null, jaSubmitted: false, acks: [] as FwAck[], acksOwed: [] as ReturnType<typeof fwAcksOwed>, canAck: false, forMe: a.level === 'FWM' };
  }
  const deadline = fwDeadline(a.paper, counted);
  const daysLeft = daysBetween(a.today, deadline);
  // A renewal FWM submitted for this paper pauses it whichever app's date it was recorded against.
  const renewal = a.renewals.find((r) => r.paper === a.paper && !r.doneAt && (r.expiresOn === counted || r.expiresOn === primaExpiresOn)) ?? null;
  // The JA app's own "renewal submitted" pauses the ladder only for the date it is about.
  const jaSubmitted = !renewal && !!ja?.renewalSubmittedOn && ja.expiresOn === counted;
  const stage = fwStage(daysLeft, !!renewal || jaSubmitted);
  const acks = (c?.fwAcks ?? []).filter((x) => x.expiresOn === counted);
  const acksOwed = fwAcksOwed(deadline, counted, stage, acks, a.today);
  return {
    ...base,
    expiresOn: counted,
    deadline,
    daysLeft,
    stage,
    renewal,
    jaSubmitted,
    acks,
    acksOwed,
    // Acknowledging needs the paper in Prima (a JA-only date is added first).
    canAck: !!c && !!a.level && acksOwed.some((x) => x.level === a.level),
    forMe: !!a.level && stage.alerted.includes(a.level),
  };
}

